    getenv(
      "KLS_ENABLE_REFACTOR_SUPERNODE_ALGORITHM5_PAYOFF_DIRECT_PREFIX_LIVE_STATE");
  return value != NULL && value[0] != '\0' &&
         !(value[0] == '0' && value[1] == '\0');
